/**
 * Layer 1 / 3a — Contract Test: Schema Snapshot
 * Auto-generated by the autonomous QE framework.
 *
 * Asserts that every public type, field, and non-null marker in schema.graphql
 * matches a committed snapshot.  Any schema change (additive or breaking) fails
 * this test until the snapshot is intentionally regenerated:
 *
 *   npx jest --updateSnapshot src/__tests__/generated/contract.snapshot.test.ts
 *
 * Also contains targeted field-presence checks for:
 *   - Entity ID fields (detect silent removals)
 *   - Parse-layer field renames (detect REST name leakage into the SDL)
 */

import {
  buildASTSchema,
  parse,
  printSchema,
  GraphQLObjectType,
  GraphQLNonNull,
} from 'graphql';
import { readFileSync } from 'fs';

// ── helpers ───────────────────────────────────────────────────────────────────

/** Remove Apollo Federation directives that plain buildASTSchema cannot parse. */
function stripFederation(sdl: string): string {
  let s = sdl;
  s = s.replace(/directive\s+@(?:contact|link)\b[\s\S]*?\bon\s+\w+(?:\s*\|\s*\w+)*\s*\n/g, '');
  s = s.replace(/extend\s+schema[\s\S]*?(?=\n(?:type|interface|union|enum|scalar|input|directive)\s)/g, '');
  s = s.replace(/@key\s*\([^)]*\)/g, '');
  s = s.replace(/@contact\s*\([^)]*\)/g, '');
  return s.replace(/\n{3,}/g, '\n\n').trim() + '\n';
}

const sdl = stripFederation(readFileSync('schema.graphql', 'utf-8'));
const schema = buildASTSchema(parse(sdl));

// ── suite ─────────────────────────────────────────────────────────────────────

describe('Generated Contract: Schema Snapshot', () => {
  // Full SDL snapshot — any change (additive or breaking) fails until
  // `--updateSnapshot` is run intentionally.
  it('SDL snapshot — update intentionally with --updateSnapshot', () => {
    expect(printSchema(schema)).toMatchSnapshot();
  });

  // ── entity ID field presence ───────────────────────────────────────────────
  // These are the fields most likely to silently disappear after a codegen bump
  // or a REST→schema rename in parse-service.ts.

  const entityChecks: Array<{ type: string; field: string; expectNonNull: boolean }> = [
    { type: 'Capsule',   field: 'id', expectNonNull: false },
    { type: 'Core',      field: 'id', expectNonNull: false },
    { type: 'Dragon',    field: 'id', expectNonNull: false },
    { type: 'Launch',    field: 'id', expectNonNull: false },
    { type: 'Launchpad', field: 'id', expectNonNull: false },
    { type: 'Landpad',   field: 'id', expectNonNull: false },
    { type: 'Payload',   field: 'id', expectNonNull: false },
    { type: 'Rocket',    field: 'id', expectNonNull: false },
    { type: 'Ship',      field: 'id', expectNonNull: false },
    { type: 'History',   field: 'id', expectNonNull: false },
    { type: 'Mission',   field: 'id', expectNonNull: false },
  ];

  it.each(entityChecks)(
    '$type.$field is present in the schema',
    ({ type, field, expectNonNull }) => {
      const t = schema.getType(type) as GraphQLObjectType | undefined;
      expect(t).toBeDefined();
      const f = t!.getFields()[field];
      expect(f).toBeDefined();
      if (expectNonNull) {
        expect(f.type).toBeInstanceOf(GraphQLNonNull);
      }
    },
  );

  // ── parse-layer field rename guards ───────────────────────────────────────
  // parse-service.ts renames REST keys to GraphQL names.
  // Verify that the SDL exposes the GraphQL name and NOT the raw REST key.
  // If a raw REST key ever appears in the schema it means a rename was dropped.

  const renamedFieldChecks: Array<{
    type: string;
    schemaName: string;
    restName: string;
  }> = [
    // parseShip renames
    { type: 'Ship',        schemaName: 'id',           restName: 'ship_id'    },
    { type: 'Ship',        schemaName: 'name',         restName: 'ship_name'  },
    { type: 'Ship',        schemaName: 'model',        restName: 'ship_model' },
    { type: 'Ship',        schemaName: 'type',         restName: 'ship_type'  },
    // Launch.links inline renames
    { type: 'LaunchLinks', schemaName: 'article_link', restName: 'article'    },
    { type: 'LaunchLinks', schemaName: 'video_link',   restName: 'webcast'    },
  ];

  it.each(renamedFieldChecks)(
    '$type exposes "$schemaName" (not raw REST key "$restName")',
    ({ type, schemaName, restName }) => {
      const t = schema.getType(type) as GraphQLObjectType | undefined;
      expect(t).toBeDefined();
      expect(t!.getFields()[schemaName]).toBeDefined();
      // The raw REST name must NOT be exposed as a schema field.
      expect(t!.getFields()[restName]).toBeUndefined();
    },
  );

  // ── deprecated query presence ──────────────────────────────────────────────
  // mission / missions / missionsResult are @deprecated but still in the SDL.
  // Verify they exist so CI catches any accidental removal.

  const deprecatedQueries = ['mission', 'missions', 'missionsResult'] as const;

  it.each(deprecatedQueries)(
    'deprecated query "%s" still present in schema (do not silently remove)',
    (queryName) => {
      const queryType = schema.getType('Query') as GraphQLObjectType;
      expect(queryType.getFields()[queryName]).toBeDefined();
    },
  );
});
